import { createHash } from "node:crypto";
import { describe, expect, it, vi } from "vitest";
import {
  trackAgentCreated,
  trackAgentFirstHeartbeat,
  trackAgentTaskCompleted,
  trackAgentTaskRun,
  trackInteractionCreated,
  trackInteractionResolved,
  trackInstallCompleted,
} from "@paperclipai/shared/telemetry";
import type { EventDimensionsMap, TelemetryClient } from "@paperclipai/shared/telemetry";

function createClient(): TelemetryClient {
  return {
    track: vi.fn(),
    hashPrivateRef: vi.fn((value: string) => createHash("sha256").update(value).digest("hex").slice(0, 16)),
  } as unknown as TelemetryClient;
}

function runtimeValue<T>(value: string): T {
  return value as T;
}

describe("shared telemetry agent events", () => {
  it("includes agent_id for agent.created", () => {
    const client = createClient();

    trackAgentCreated(client, {
      agentRole: "engineer",
      agentId: "11111111-1111-4111-8111-111111111111",
    });

    expect(client.track).toHaveBeenCalledWith("agent.created", {
      agent_role: "engineer",
      agent_id: "11111111-1111-4111-8111-111111111111",
    });
  });

  it("passes an unrecognized agent role through for backend normalization", () => {
    const client = createClient();

    trackAgentCreated(client, {
      agentRole: runtimeValue<EventDimensionsMap["agent.created"]["agent_role"]>("coder"),
      agentId: "44444444-4444-4444-8444-444444444444",
    });

    expect(client.track).toHaveBeenCalledWith("agent.created", {
      agent_role: "coder",
      agent_id: "44444444-4444-4444-8444-444444444444",
    });
  });

  it("includes agent_id for agent.first_heartbeat", () => {
    const client = createClient();

    trackAgentFirstHeartbeat(client, {
      agentRole: "engineer",
      agentId: "22222222-2222-4222-8222-222222222222",
    });

    expect(client.track).toHaveBeenCalledWith("agent.first_heartbeat", {
      agent_role: "engineer",
      agent_id: "22222222-2222-4222-8222-222222222222",
    });
  });

  it("includes agent_id for agent.task_completed", () => {
    const client = createClient();

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
    });

    expect(client.track).toHaveBeenCalledWith("agent.task_completed", {
      agent_role: "qa",
      agent_id: "33333333-3333-4333-8333-333333333333",
      adapter_type: "codex_local",
    });
  });

  it("hashes the task id for agent.task_completed and never sends the raw value", () => {
    const client = createClient();
    const rawTaskId = "11111111-1111-4111-8111-111111111111";

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
      taskId: rawTaskId,
    });

    expect(client.hashPrivateRef).toHaveBeenCalledWith(rawTaskId);
    const sentDimensions = vi.mocked(client.track).mock.calls[0]?.[1] as Record<string, unknown>;
    expect(sentDimensions.task_id).toMatch(/^[0-9a-f]{16}$/);
    expect(sentDimensions.task_id).not.toBe(rawTaskId);
    expect(JSON.stringify(sentDimensions)).not.toContain(rawTaskId);
  });

  it("omits task_id for agent.task_completed when the caller gives no task id", () => {
    const client = createClient();

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
    });

    expect(client.hashPrivateRef).not.toHaveBeenCalled();
    expect(client.track).toHaveBeenCalledWith("agent.task_completed", {
      agent_role: "qa",
      agent_id: "33333333-3333-4333-8333-333333333333",
      adapter_type: "codex_local",
    });
  });

  it("sends all ten dimensions for agent.task_run when present", () => {
    const client = createClient();
    const rawTaskId = "22222222-2222-4222-8222-222222222222";

    trackAgentTaskRun(client, {
      agentId: "44444444-4444-4444-8444-444444444444",
      state: "succeeded",
      adapterType: "claude_local",
      agentRole: "engineer",
      model: "claude-sonnet-5",
      durationSeconds: 12.5,
      inputTokens: 100,
      outputTokens: 200,
      cachedTokens: 50,
      taskId: rawTaskId,
    });

    expect(client.hashPrivateRef).toHaveBeenCalledWith(rawTaskId);
    const sentDimensions = vi.mocked(client.track).mock.calls[0]?.[1] as Record<string, unknown>;
    expect(sentDimensions).toMatchObject({
      agent_id: "44444444-4444-4444-8444-444444444444",
      state: "succeeded",
      adapter_type: "claude_local",
      agent_role: "engineer",
      model: "claude-sonnet-5",
      duration_seconds: 12.5,
      input_tokens: 100,
      output_tokens: 200,
      cached_tokens: 50,
    });
    expect(sentDimensions.task_id).toMatch(/^[0-9a-f]{16}$/);
  });

  it("omits every absent optional dimension for agent.task_run", () => {
    const client = createClient();

    trackAgentTaskRun(client, {
      agentId: "55555555-5555-4555-8555-555555555555",
      state: "failed",
    });

    expect(client.hashPrivateRef).not.toHaveBeenCalled();
    expect(client.track).toHaveBeenCalledWith("agent.task_run", {
      agent_id: "55555555-5555-4555-8555-555555555555",
      state: "failed",
    });
  });

  it("keeps non-agent event dimensions unchanged", () => {
    const client = createClient();

    trackInstallCompleted(client, { adapterType: "codex_local" });

    expect(client.track).toHaveBeenCalledWith("install.completed", {
      adapter_type: "codex_local",
    });
    expect(client.track).not.toHaveBeenCalledWith(
      "install.completed",
      expect.objectContaining({ agent_id: expect.any(String) }),
    );
  });

  it("passes interaction.resolved enum dimensions through for backend normalization", () => {
    const client = createClient();

    trackInteractionResolved(client, {
      interactionKind: runtimeValue<EventDimensionsMap["interaction.resolved"]["interaction_kind"]>(
        "single_confirmation",
      ),
      status: "accepted",
      resolvedByKind: runtimeValue<EventDimensionsMap["interaction.resolved"]["resolved_by_kind"]>("operator"),
      resolutionReason: "accepted",
      createdByKind: "agent",
      creatorAgentRole: runtimeValue<EventDimensionsMap["interaction.resolved"]["creator_agent_role"]>("coder"),
      continuationPolicy: runtimeValue<EventDimensionsMap["interaction.resolved"]["continuation_policy"]>(
        "wake_everyone",
      ),
      targetType: "issue_document",
      optionCount: 2,
      selectedOptionCount: 1,
      skippedTaskCount: 3,
      legacyInheritedRestriction: true,
    });

    expect(client.track).toHaveBeenCalledWith("interaction.resolved", {
      interaction_kind: "single_confirmation",
      status: "accepted",
      resolved_by_kind: "operator",
      resolution_reason: "accepted",
      created_by_kind: "agent",
      creator_agent_role: "coder",
      continuation_policy: "wake_everyone",
      target_type: "issue_document",
      option_count: 2,
      selected_option_count: 1,
      skipped_task_count: 3,
      legacy_inherited_restriction: true,
    });
  });

  it("emits only enum and boolean dimensions for interaction creation compatibility", () => {
    const client = createClient();

    trackInteractionCreated(client, {
      interactionKind: "request_confirmation",
      usedDeprecatedResolverPolicyAlias: true,
    });

    expect(client.track).toHaveBeenCalledWith("interaction.created", {
      interaction_kind: "request_confirmation",
      used_deprecated_resolver_policy_alias: true,
    });
  });
});

//! Project [`BudgetEvent`](ironclaw_resources::BudgetEvent) records.
//!
//! The runtime owns a `tokio::sync::broadcast::Sender<BudgetEvent>` via
//! [`BroadcastBudgetEventSink`]. Production composition spawns a
//! [`BudgetEventProjection`] task at runtime construction; the task
//! receives every emitted event and hands it to a
//! [`BudgetEventObserver`] for delivery.
//!
//! The default observer logs at `debug!`. Production owners that need to
//! fan budget events out to SSE / WS / external telemetry pass their own
//! observer through
//! [`RebornRuntimeInput::with_budget_event_observer`](crate::RebornRuntimeInput).

use std::sync::Arc;

use ironclaw_resources::{BroadcastBudgetEventSink, BudgetEvent};
use tokio::sync::broadcast;
use tokio::task::JoinHandle;
use tokio_util::sync::CancellationToken;

/// Observer that receives every projected `BudgetEvent` in arrival order.
///
/// Implementors must not panic. The projection task does not isolate
/// the observer in a separate task — a panic propagates to the
/// projection task and shuts it down. Production observers should
/// catch their own errors and convert them to log lines or telemetry.
pub trait BudgetEventObserver: Send + Sync + std::fmt::Debug + 'static {
    fn observe(&self, event: BudgetEvent);
}

/// Default observer that logs every event at `debug!`. Used as the
/// fallback when no production owner installs a richer projection
/// (e.g. tracing-only deploys, standalone binaries that just want the
/// observability without an SSE bridge).
#[derive(Debug, Default, Clone, Copy)]
pub(crate) struct TracingBudgetEventObserver;

impl BudgetEventObserver for TracingBudgetEventObserver {
    fn observe(&self, event: BudgetEvent) {
        tracing::debug!(?event, "reborn budget event observed");
    }
}

/// Background task that drains a `BudgetEvent` broadcast receiver and
/// hands every event to the configured observer.
///
/// Cancelled by the parent runtime's shutdown via the internal
/// [`CancellationToken`]. The handle is held by `RebornRuntime` and
/// awaited inside `RebornRuntime::shutdown` so the task always exits
/// before the runtime drops.
#[derive(Debug)]
pub(crate) struct BudgetEventProjection {
    handle: JoinHandle<()>,
    cancel: CancellationToken,
}

impl BudgetEventProjection {
    /// Subscribe to `sink` and spawn the projection task.
    pub(crate) fn spawn(
        sink: &BroadcastBudgetEventSink,
        observer: Arc<dyn BudgetEventObserver>,
    ) -> Self {
        let cancel = CancellationToken::new();
        let receiver = sink.subscribe();
        let cancel_for_task = cancel.clone();
        let handle = tokio::spawn(run_projection(receiver, observer, cancel_for_task));
        Self { handle, cancel }
    }

    /// Trigger cancellation and await the projection task. Idempotent
    /// — calling shutdown after the task has already exited is
    /// harmless (the `CancellationToken` only fires once and the
    /// `JoinHandle::await` immediately returns the cached result).
    pub(crate) async fn shutdown(self) {
        self.cancel.cancel();
        if let Err(error) = self.handle.await {
            if error.is_panic() {
                tracing::error!(%error, "budget event projection task panicked during shutdown");
            } else {
                tracing::debug!(%error, "budget event projection task cancelled during shutdown");
            }
        }
    }
}

async fn run_projection(
    mut receiver: broadcast::Receiver<BudgetEvent>,
    observer: Arc<dyn BudgetEventObserver>,
    cancel: CancellationToken,
) {
    loop {
        tokio::select! {
            _ = cancel.cancelled() => {
                tracing::debug!("budget event projection cancelled — exiting");
                return;
            }
            received = receiver.recv() => {
                match received {
                    Ok(event) => observer.observe(event),
                    Err(broadcast::error::RecvError::Lagged(skipped)) => {
                        tracing::warn!(
                            skipped,
                            "budget event projection fell behind the broadcast buffer; \
                             dropping {skipped} events and resuming"
                        );
                    }
                    Err(broadcast::error::RecvError::Closed) => {
                        tracing::debug!("budget event broadcast closed — projection exiting");
                        return;
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::Utc;
    use ironclaw_host_api::ids::{TenantId, UserId};
    use ironclaw_resources::{
        BudgetEventSink, BudgetWarning, ResourceAccount, ResourceDimension, ResourceValue,
    };
    use rust_decimal::Decimal;
    use std::sync::Mutex;
    use std::time::Duration;

    #[derive(Debug, Default)]
    struct CapturingObserver {
        events: Mutex<Vec<BudgetEvent>>,
    }

    impl BudgetEventObserver for CapturingObserver {
        fn observe(&self, event: BudgetEvent) {
            self.events.lock().unwrap().push(event);
        }
    }

    fn user_warning() -> BudgetWarning {
        BudgetWarning {
            account: ResourceAccount::user(TenantId::new("t").unwrap(), UserId::new("u").unwrap()),
            dimension: ResourceDimension::Usd,
            utilization: 0.85,
            limit: ResourceValue::Decimal(Decimal::from(10)),
            period_end: None,
        }
    }

    /// Drives the projection task end-to-end: emit a `Warned` event
    /// through the broadcast sink, wait briefly for the task to drain
    /// it, and assert the observer received it. Exercises the
    /// production wiring shape — broadcast sink construction →
    /// `spawn` → task picks up event → observer invocation.
    #[tokio::test]
    async fn projection_forwards_every_event_to_observer() {
        let sink = BroadcastBudgetEventSink::default();
        let observer = Arc::new(CapturingObserver::default());
        let observer_for_projection: Arc<dyn BudgetEventObserver> = Arc::clone(&observer) as Arc<_>;
        let projection = BudgetEventProjection::spawn(&sink, observer_for_projection);

        sink.emit(BudgetEvent::Warned {
            warning: user_warning(),
            at: Utc::now(),
        });

        // Allow the spawned task to drain the broadcast queue. The
        // test stays small (~20 ms) so a slow runner does not turn
        // it flaky; on a healthy machine the receive is sub-ms.
        let observed = tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                if observer.events.lock().unwrap().len() == 1 {
                    return;
                }
                tokio::task::yield_now().await;
            }
        })
        .await;
        assert!(observed.is_ok(), "projection did not deliver event in time");

        projection.shutdown().await;

        let events = observer.events.lock().unwrap();
        assert_eq!(events.len(), 1);
        assert!(matches!(events[0], BudgetEvent::Warned { .. }));
    }

    /// Regression: shutdown is non-blocking even when no events have
    /// been emitted. Catches a subtle bug shape where the projection
    /// task waits on `recv()` and only exits when a message arrives.
    #[tokio::test]
    async fn shutdown_cancels_the_task_even_with_no_events() {
        let sink = BroadcastBudgetEventSink::default();
        let observer: Arc<dyn BudgetEventObserver> = Arc::new(TracingBudgetEventObserver);
        let projection = BudgetEventProjection::spawn(&sink, observer);

        let shutdown = tokio::time::timeout(Duration::from_secs(2), projection.shutdown()).await;
        assert!(
            shutdown.is_ok(),
            "shutdown blocked waiting for an event; cancellation token did not fire"
        );
    }

    /// Regression: after `shutdown()` returns, subsequent emits do
    /// not crash and are not observed. Locks the contract that
    /// shutdown cleanly drops the broadcast Receiver.
    #[tokio::test]
    async fn events_emitted_after_shutdown_are_not_observed() {
        let sink = BroadcastBudgetEventSink::default();
        let observer = Arc::new(CapturingObserver::default());
        let observer_for_projection: Arc<dyn BudgetEventObserver> = Arc::clone(&observer) as Arc<_>;
        let projection = BudgetEventProjection::spawn(&sink, observer_for_projection);
        projection.shutdown().await;

        sink.emit(BudgetEvent::Warned {
            warning: user_warning(),
            at: Utc::now(),
        });
        tokio::time::sleep(Duration::from_millis(20)).await;

        assert!(observer.events.lock().unwrap().is_empty());
    }
}

//! Quarantine audit emission for the third-party hook projection path.
//!
//! Composition is a pre-run phase (no run-scoped `LoopHostMilestoneSink` exists
//! yet), so quarantine decisions are surfaced via `tracing` at a stable,
//! filterable target rather than a durable sink. Durable surfacing is a
//! documented follow-up — and a hard prerequisite for production enablement of
//! `HOOKS_THIRD_PARTY_ENABLED`, alongside `openat2` FS hardening. See the
//! production-enablement gate on
//! [`crate::observability::hooks::HooksActivationConfig`] for the full prerequisite list.

/// Structured target for the security-audit `tracing` channel. Composition is a
/// pre-run phase (no run-scoped `LoopHostMilestoneSink` exists yet), so
/// quarantine decisions are surfaced via `tracing` at this stable target rather
/// than a durable sink. Durable surfacing is a documented follow-up.
pub(super) const SECURITY_AUDIT_TARGET: &str = "security_audit";

/// Emit a `hook.quarantined` security-audit event for an extension whose hooks
/// were dropped during projection.
///
/// Pre-run composition has no durable milestone sink, so this surfaces via
/// `tracing` at the stable [`SECURITY_AUDIT_TARGET`]. This is a background /
/// composition path, so per the REPL/TUI logging rule it uses `debug!` (never
/// `info!`/`warn!`, which corrupt the interactive display); the dedicated
/// `security_audit` target keeps the event filterable for operators.
pub(super) fn emit_hook_quarantined(
    tenant_id: &ironclaw_host_api::ids::TenantId,
    extension_id: &str,
    reason: &str,
    hooks_dropped: usize,
) {
    #[cfg(test)]
    test_capture::record(tenant_id, extension_id);

    tracing::debug!(
        target: SECURITY_AUDIT_TARGET,
        event = "hook.quarantined",
        tenant_id = %tenant_id.as_str(),
        extension_id = %extension_id,
        reason = %reason,
        hooks_dropped = hooks_dropped,
        "third-party extension hooks quarantined during projection"
    );
}

/// Deterministic, thread-local capture of quarantine-audit attribution for
/// tests. The `tracing` channel is the production observability surface, but
/// asserting on it from a unit test is racy: a sibling test that installs a
/// global subscriber raises `tracing`'s process-wide max-level hint and can
/// suppress the `debug!` event before any thread-local subscriber sees it.
/// This thread-local sink records the `(tenant_id, extension_id)` pairs emitted
/// on the CURRENT thread regardless of any global `tracing` filter, so the
/// caller-driven attribution test is deterministic under parallel `cargo test`.
#[cfg(test)]
pub(super) mod test_capture {
    use std::cell::RefCell;

    thread_local! {
        static CAPTURED: RefCell<Option<Vec<(String, String)>>> = const { RefCell::new(None) };
    }

    /// Run `body` with capture armed on this thread; returns the recorded
    /// `(tenant_id, extension_id)` quarantine pairs. Nesting is not supported
    /// (a single test scope at a time), which matches the per-test usage.
    pub(in crate::observability::hooks) fn with_capture<R>(
        body: impl FnOnce() -> R,
    ) -> (R, Vec<(String, String)>) {
        CAPTURED.with(|cell| *cell.borrow_mut() = Some(Vec::new()));
        let result = body();
        let captured = CAPTURED.with(|cell| cell.borrow_mut().take().unwrap_or_default());
        (result, captured)
    }

    pub(super) fn record(tenant_id: &ironclaw_host_api::ids::TenantId, extension_id: &str) {
        CAPTURED.with(|cell| {
            if let Some(buffer) = cell.borrow_mut().as_mut() {
                buffer.push((tenant_id.as_str().to_string(), extension_id.to_string()));
            }
        });
    }
}

// The mobile app's event vocabulary and the property allowlist for each event.
//
// Split from any React Native import so the rules are unit-testable, the same
// split the codebase already uses for onboarding.ts vs onboardingStore.ts.
//
// The allowlist is the privacy contract. The phone can see session titles, PR
// titles, project names, terminal output, and the connection password, none of
// which may ever reach PostHog. sanitize.ts iterates THIS allowlist, never the
// caller's payload, so a property nobody registered here is dropped rather than
// forwarded. Adding a field is a deliberate edit to this file, reviewable in one
// place.

export const MOBILE_EVENTS = {
	// Unions with the desktop heartbeat of the same name; the `client` context
	// property separates mobile from desktop. One "active users" metric, split by
	// surface.
	active: "ao.v2.app.active",

	// A brand-new credential was validated by scanning a QR or manual entry. The
	// phone-side confirmation of the daemon's ao.mobile.device_connected.
	paired: "ao.v2.mobile_app.paired",
	// The stored config reconnected on launch (no user pairing action).
	connected: "ao.v2.mobile_app.connected",

	onboardingStarted: "ao.v2.mobile_app.onboarding_started",
	onboardingCompleted: "ao.v2.mobile_app.onboarding_completed",
	onboardingSkipped: "ao.v2.mobile_app.onboarding_skipped",

	// A push notification opened the app. The retention signal.
	notificationOpened: "ao.v2.mobile_app.notification_opened",

	// A core action was taken (spawn, merge, kill, ...). Drives "most-used
	// feature". Screen-view tracking was dropped by product decision: feature
	// events answer the usage question without a second per-navigation stream.
	featureUsed: "ao.v2.mobile_app.feature_used",

} as const;

export type MobileEventName = (typeof MOBILE_EVENTS)[keyof typeof MOBILE_EVENTS];

/**
 * Allowed property keys per event, with the closed vocabulary for enum fields.
 *
 * A key absent here is dropped. A key present with a `oneOf` is dropped unless
 * the value is in that set. A key present with `kind: "count"` keeps a finite
 * non-negative integer; `kind: "flag"` keeps a boolean. No `kind: "string"`
 * exists on purpose: there is no free-text field in the mobile vocabulary, so a
 * title or path can never ride along.
 */
export type PropRule =
	| { readonly oneOf: readonly string[] }
	| { readonly kind: "count" }
	| { readonly flag: true };

export const MOBILE_ALLOWLIST: Record<string, Readonly<Record<string, PropRule>>> = {
	[MOBILE_EVENTS.active]: {},
	[MOBILE_EVENTS.paired]: {
		method: { oneOf: ["qr", "manual"] },
		from_onboarding: { flag: true },
	},
	[MOBILE_EVENTS.connected]: {
		trigger: { oneOf: ["launch", "reconnect"] },
	},
	[MOBILE_EVENTS.onboardingStarted]: {},
	[MOBILE_EVENTS.onboardingCompleted]: {},
	[MOBILE_EVENTS.onboardingSkipped]: {},
	[MOBILE_EVENTS.notificationOpened]: {
		// notificationView already maps a push to a small set of destinations.
		target: { oneOf: ["session", "prs"] },
		cold_start: { flag: true },
	},
	[MOBILE_EVENTS.featureUsed]: {
		feature: {
			oneOf: ["spawn", "merge", "kill", "restore", "conductor", "send", "handoff"],
		},
		outcome: { oneOf: ["succeeded", "failed"] },
		// The chat/tui interface. Set on spawn and conductor (the mode the session
		// starts in) and on handoff (the mode it switches to). Absent on the other
		// features, which are mode-agnostic. Only the two enum values ever leave the
		// device; no titles or paths ride on this.
		mode: { oneOf: ["chat", "tui"] },
	},
};

package telemetry

import (
	"context"
	"sync"
	"time"

	"github.com/aoagents/agent-orchestrator/backend/internal/ports"
)

// AggregatingSink folds every occurrence of a bursty event in a flush window
// into a single rollup event carrying a count, so cost scales with flush
// windows (one event/minute per name, worst case), not occurrences, and the
// true magnitude of a burst is still visible.
//
// PostHog bills per event ingested, regardless of what's in the payload. For
// event names that are prone to bursts (a 5xx storm, a panic loop, a retry
// hammering a bad command), per-occurrence rate limiting bounds the bill but
// throws away everything past the cap - a storm of 10,000 errors and one of
// 6 both show up as "5, then silence."
//
// Only event names named at construction are aggregated; everything else
// passes straight through to next unchanged, so per-occurrence semantics and
// RateLimitedSink's existing caps still apply to names this sink doesn't own.
type AggregatingSink struct {
	next       ports.EventSink
	names      map[string]struct{}
	flushEvery time.Duration

	mu      sync.Mutex
	buckets map[string]*aggBucket
	closed  bool
	done    chan struct{}
}

type aggBucket struct {
	windowStart time.Time
	count       int
	sample      ports.TelemetryEvent
}

// NewAggregatingSink wraps next, folding occurrences of any event name in
// names into one rollup event per flushEvery window. Event names not in
// names are forwarded to next immediately, unaggregated. Starts a background
// flush loop; call Close to stop it and flush anything buffered.
func NewAggregatingSink(next ports.EventSink, names []string, flushEvery time.Duration) *AggregatingSink {
	nameSet := make(map[string]struct{}, len(names))
	for _, n := range names {
		nameSet[n] = struct{}{}
	}
	s := &AggregatingSink{
		next:       next,
		names:      nameSet,
		flushEvery: flushEvery,
		buckets:    make(map[string]*aggBucket),
		done:       make(chan struct{}),
	}
	go s.flushLoop()
	return s
}

// Emit forwards ev immediately if its name isn't aggregated; otherwise it is
// folded into the current window's bucket for that name and only reaches
// next as part of the next rollup.
func (s *AggregatingSink) Emit(ctx context.Context, ev ports.TelemetryEvent) {
	if _, ok := s.names[ev.Name]; !ok {
		s.next.Emit(ctx, ev)
		return
	}

	s.mu.Lock()
	b, ok := s.buckets[ev.Name]
	if !ok {
		b = &aggBucket{windowStart: time.Now()}
		s.buckets[ev.Name] = b
	}
	b.count++
	b.sample = ev // last occurrence wins; only used for dims (level/source/ids), count/window carry the volume
	s.mu.Unlock()
}

func (s *AggregatingSink) flushLoop() {
	ticker := time.NewTicker(s.flushEvery)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			s.flush(context.Background())
		case <-s.done:
			return
		}
	}
}

// flush emits one rollup event per non-empty bucket and clears the buckets.
func (s *AggregatingSink) flush(ctx context.Context) {
	s.mu.Lock()
	buckets := s.buckets
	s.buckets = make(map[string]*aggBucket)
	s.mu.Unlock()

	now := time.Now().UTC()
	for name, b := range buckets {
		payload := make(map[string]any, len(b.sample.Payload)+3)
		for k, v := range b.sample.Payload {
			payload[k] = v
		}
		payload["count"] = b.count
		// Stringified (not time.Time): sanitizeRemoteValue's allowlist
		// filter only understands JSON scalar types (string/bool/number), so
		// a raw time.Time here would silently vanish before reaching
		// PostHog even once the field name is allowlisted.
		payload["window_start"] = b.windowStart.UTC().Format(time.RFC3339Nano)
		payload["window_end"] = now.Format(time.RFC3339Nano)

		s.next.Emit(ctx, ports.TelemetryEvent{
			Name:       name,
			Source:     b.sample.Source,
			OccurredAt: now,
			Level:      b.sample.Level,
			ProjectID:  b.sample.ProjectID,
			SessionID:  b.sample.SessionID,
			RequestID:  b.sample.RequestID,
			Payload:    payload,
		})
	}
}

// Close stops the flush loop, emits one final rollup for anything buffered
// since the last tick, and closes the wrapped sink.
func (s *AggregatingSink) Close(ctx context.Context) error {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return s.next.Close(ctx)
	}
	s.closed = true
	s.mu.Unlock()

	close(s.done)
	s.flush(ctx)
	return s.next.Close(ctx)
}

