}

#[cfg(feature = "telemetry")]
fn build_payload(name: &str, event: Value, event_ts: &str, sent_ts: &str) -> Value {
    json!({
        "browserType": "undefined",
        "clientId": CLIENT_ID,
        "clientType": "Native",
